use verus::*;

verus! {

/// Checks if the input vector `v` is non-empty and all characters are lowercase ASCII letters 'a'..='z'.
/// 
/// # Specification
/// Requires nothing.
/// Ensures that the return is true iff:
/// - v.len() > 0, and
/// - for every character c in v, c >= 'a' and c <= 'z'
fn check_all_lowercase(v: &Vec<char>) -> bool
    ensures |result: bool| result == (v.len() > 0 && forall|i: usize| (i < v.len()) ==> (v[i] >= 'a' && v[i] <= 'z'))
{
    let mut i: usize = 0;
    while i < v.len()
        invariant i <= v.len()
        invariant forall|j: usize| j < i ==> (v[j] >= 'a' && v[j] <= 'z')
    {
        if !(v[i] >= 'a' && v[i] <= 'z') {
            return false;
        }
        i = i + 1;
    }
    // Non-empty check:
    if v.len() == 0 { return false; }
    true
}

/// Given an input vector of characters, returns a vector with a single character:
/// - ['a'] if and only if the input is all lowercase (non-empty and all chars between 'a'..'z')
/// - ['A'] otherwise (empty or any non-lowercase character)
/// 
/// Ensures output length == 1 and output is either ['a'] or ['A']
/// 
fn solve(input: Vec<char>) -> Vec<char>
    ensures |res: Vec<char>| res.len() == 1 &&
        (res[0] == 'a' ==> check_all_lowercase(&input)) &&
        (res[0] == 'A' ==> !check_all_lowercase(&input))
{
    if check_all_lowercase(&input) {
        vec!['a']
    } else {
        vec!['A']
    }
}

}